  function playMelodySegment(session,tracks,startTick,endTick,request,looping){const audio=state.melodyAudio,synth=melodySynth();if(request!==audio.playRequest)return{ok:false,reason:'cancelled'};synth.stopPlayback();const transport=editorPlaybackTransport(session,{playing:true,currentTick:startTick}),result=scheduleTrackPlayback(synth,tracks,{...transport,startTick,endTick,leadSeconds:looping?0:undefined,playbackState:audio.playbackState});audio.playing=result.ok&&result.noteCount>0;audio.transport={...transport,playing:audio.playing,currentTick:startTick,playbackStartOrigin:result.playbackStart,activePlaybackTrackIds:transport?.activePlaybackTrackIds||[]};audio.status=audio.playing?(looping?'3Trackループ再生中':'3Track再生中'):'この範囲に再生できるノートがありません';if(audio.playing){const duration=looping?(result.timelineDurationSeconds??Math.max(1,endTick-startTick)*result.secondsPerTick)*1000:result.durationMs;audio.playbackTimer=root.setTimeout?.(()=>{if(request===audio.playRequest)editorStopMelody()},duration);startEditorPlayhead(session,result,request)}return result}
  async function editorPlayMelody(){const session=state.midiEditor,tracks=editorPlaybackTracks(session),active=editorActivePlaybackTracks(session),audio=state.melodyAudio;if(!active.some(track=>track.notes.length))return notice('再生するTrackノートがありません。','info');if(audio.starting||audio.playing)return{ok:false,reason:'already-playing'};const loop=editorLoop(session),timeline=editorTimelineTicks(session),looping=loop.enabled,startTick=looping&&(session.playheadTick<loop.start||session.playheadTick>=loop.end)?loop.start:Math.max(0,Number(session.playheadTick)||0),endTick=looping?loop.end:undefined;editorStopMelody(false,false);setEditorPlayhead(session,startTick);const request=++audio.playRequest;audio.starting=true;audio.status='3Track再生を準備中';repaintEditor();if(!await unlockMelodyAudio()){if(request===audio.playRequest){audio.starting=false;audio.status=''}return notice('このブラウザではPlayback音源を利用できません。','error')}if(request!==audio.playRequest)return{ok:false,reason:'cancelled'};audio.starting=false;const result=playMelodySegment(session,tracks,startTick,Math.min(endTick??timeline.totalTicks,timeline.totalTicks),request,looping);if(result.ok&&result.noteCount>0&&editorTransportSettings(session).metronomeEnabled){const timing=editorBeatTiming(session),contextNow=melodySynth()?.context?.currentTime,leadMs=Number.isFinite(result.playbackStart)&&Number.isFinite(contextNow)?Math.max(0,(result.playbackStart-contextNow)*1000):0,startBeat=Math.ceil(startTick/timing.beatTicks),beatDelay=(startBeat*timing.beatTicks-startTick)*60000/(timing.tempo*(Number(session.midiData.ppq)||480));startEditorMetronome({startAt:midiClock()+leadMs+beatDelay,beatIndex:startBeat})}repaintEditor();return result}
  function editorToggleMelodyPlayback(){const audio=state.melodyAudio;return audio.playing||audio.starting||state.midiInput.recording?editorStopTransport():editorPlayMelody()}
  function editorStopMelody(repaint=true,resetPlayhead=true){const audio=state.melodyAudio;audio.playRequest++;if(audio.playbackTimer)root.clearTimeout?.(audio.playbackTimer);audio.playbackTimer=null;if(audio.playbackFrame!==null)root.cancelAnimationFrame?.(audio.playbackFrame);audio.playbackFrame=null;audio.synth?.stopPlayback();stopEditorMetronome();audio.starting=false;audio.playing=false;audio.status='';if(audio.transport)audio.transport={...audio.transport,playing:false,currentTick:resetPlayhead?0:Number(state.midiEditor?.playheadTick)||0};if(resetPlayhead)setEditorPlayhead(state.midiEditor,0);if(repaint)repaintEditor()}
  function transposeInput(panel=root.document?.querySelector?.('#melodyTransposePanel')){const field=name=>panel?.querySelector?.(`[name="${name}"]`),checked=name=>panel?.querySelector?.(`input[name="${name}"]:checked`);return{fromKey:field('transposeFromKey')?.value||state.midiEditor?.transposeSettings?.fromKey||'C',toKey:field('transposeToKey')?.value||state.midiEditor?.transposeSettings?.toKey||'C',target:checked('transposeTarget')?.value||state.midiEditor?.transposeSettings?.target||'all',measureFrom:Number(field('transposeMeasureFrom')?.value),measureTo:Number(field('transposeMeasureTo')?.value),direction:checked('transposeDirection')?.value||state.midiEditor?.transposeSettings?.direction||'shortest'}}
