  async function saveMidiEditor(options={}){const pending=state.midiEditorSavePromise;if(pending)await pending;const session=state.midiEditor;if(!session?.dirty)return{ok:true,skipped:true};try{const project=await repository.get(session.projectId);if(!project)throw Error('保存対象のプロジェクトが見つかりません。');const bpm=Number(session.midiData.tempo),updated={...project,musicalSettings:{...project.musicalSettings,bpm},midiData:root.MusicStudioEditor.clone(session.midiData),revision:(project.revision||1)+1,updatedAt:now()};await repository.put(updated);state.projects=state.projects.map(item=>item.projectId===updated.projectId?updated:item);root.MusicStudioEditor.markSaved(session,updated.midiData);if(!options.silent)notice(session.dirty?'保存中に新しい変更が加わりました。もう一度保存してください。':'MIDI編集をプロジェクトへ保存しました。',session.dirty?'info':'success');return{ok:true,project:updated,stale:session.dirty}}catch(error){console.error(error);session.dirty=true;notice('MIDI編集を保存できませんでした。ノートは画面に保持されています。','error');return{ok:false,error}}}
